(7534586, 1204995, 12253, '<td valign="top">Great image...congrats!</td>', 'Great image...congrats!', '2017-09-12 01:22:51.000000', NULL, 0),
(7534590, 1204995, 123833, '<td valign="top">Nice, congrats on the blue (I would have done a spot edit and desaturated her top to make her blend into the chair :)</td>', 'Nice, congrats on the blue (I would have done a spot edit and desaturated her top to make her blend into the chair :)', '2017-09-12 02:58:08.000000', NULL, 0),
(7534607, 1204995, 135744, '<td valign="top">Your world is so colourful! Wonderful photo - congrats! For the record, I would not have cropped this image - I don''t mind the lady on the right and think it would have been a very tricky job to clone her away.</td>', 'Your world is so colourful! Wonderful photo - congrats! For the record, I would not have cropped this image - I don''t mind the lady on the right and think it would have been a very tricky job to clone her away.', '2017-09-12 07:36:24.000000', NULL, 0),
(7534608, 1205096, 135744, '<td valign="top">Nice purchase. And nice photo too. Congrats!</td>', 'Nice purchase. And nice photo too. Congrats!', '2017-09-12 07:37:13.000000', NULL, 0),
(7534640, 1205096, 97166, '<td valign="top">9 from me as well. The coloring was magnificent. An inviting photo. All I wanted to do was lie down and pull that blanket over me.</td>', '9 from me as well. The coloring was magnificent. An inviting photo. All I wanted to do was lie down and pull that blanket over me.', '2017-09-12 13:44:59.000000', NULL, 0),
